import json
import os
import sys
from urllib.error import HTTPError, URLError
from urllib.parse import urlencode, urlsplit
from urllib.request import Request, urlopen

def build_payload(args):
    query = args.get("query")
    if not isinstance(query, str) or not query.strip():
        raise ValueError("请提供搜索关键词")
    query = query.strip()
    if len(query) > 500:
        raise ValueError("搜索关键词不能超过 500 个字符")
    return {
        "url": "https://www.bing.com/search?" + urlencode({"q": query}),
        "format": "markdown",
        "content_scope": "full",
        "include_links": True,
        "include_images": False,
        "max_chars": output_limit(args),
        "wait_for_selector": "#b_results",
    }

PAGEWEAVE_URL = os.environ.get("PAGEWEAVE_URL", "http://172.31.100.240:7779/extract")
MAX_RESPONSE_BYTES = 1024 * 1024


def output_limit(args):
    limit = args.get("max_chars", 12000)
    if type(limit) is not int or not 1 <= limit <= 50000:
        raise ValueError("max_chars 必须是 1 到 50000 之间的整数")
    return limit


def error_detail(body, status):
    try:
        result = json.loads(body)
    except (ValueError, UnicodeDecodeError):
        return f"PageWeave HTTP {status}: 服务未返回有效的 JSON 错误信息"
    if not isinstance(result, dict):
        return f"PageWeave HTTP {status}: 错误响应格式无效"
    error = result.get("error", {})
    if not isinstance(error, dict):
        error = {}
    code = error.get("code", "unknown_error")
    message = error.get("message", "服务未提供错误原因")
    request_id = result.get("request_id", "")
    detail = f"PageWeave HTTP {status} [{code}]: {message}"
    if request_id:
        detail += f" (request_id={request_id})"
    return detail


def request_pageweave(payload):
    endpoint = urlsplit(PAGEWEAVE_URL.strip())
    if endpoint.scheme.lower() not in ("http", "https") or not endpoint.hostname:
        raise ValueError("PAGEWEAVE_URL 必须是完整的 HTTP 或 HTTPS 接口地址")
    if endpoint.username is not None or endpoint.password is not None:
        raise ValueError("PAGEWEAVE_URL 不支持内嵌用户名或密码")
    body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    if len(body) > 16384:
        raise ValueError("请求内容超过 PageWeave 默认的 16384 字节限制")
    request = Request(
        PAGEWEAVE_URL.strip(),
        data=body,
        headers={"Content-Type": "application/json", "Accept": "application/json"},
        method="POST",
    )
    try:
        with urlopen(request, timeout=30) as response:
            raw = response.read(MAX_RESPONSE_BYTES + 1)
    except HTTPError as error:
        with error:
            detail = error_detail(error.read(65536), error.code)
        raise RuntimeError(detail) from error
    except (URLError, OSError) as error:
        reason = getattr(error, "reason", error)
        raise RuntimeError(f"PageWeave 连接失败或超时: {reason}") from error
    if len(raw) > MAX_RESPONSE_BYTES:
        raise RuntimeError("PageWeave 响应超过 1 MiB，未读取完整内容")
    try:
        result = json.loads(raw)
    except (ValueError, UnicodeDecodeError) as error:
        raise RuntimeError("PageWeave 返回的内容不是有效 JSON") from error
    if not isinstance(result, dict):
        raise RuntimeError("PageWeave 响应必须是 JSON 对象")
    content = result.get("content")
    if not isinstance(content, str) or not content.strip():
        raise RuntimeError("PageWeave 没有返回有效的网页内容")
    return result


def format_result(result, requested_url):
    title = result.get("title") or "未提供标题"
    source = result.get("final_url") or requested_url
    lines = [f"标题: {title}", f"来源: {source}"]
    if result.get("truncated") is True:
        lines.append("提示: 内容已达到长度上限，并非完整网页。")
    warning_labels = {
        "fallback_full_content": "正文提取采用了整页内容兜底",
        "render_wait_limit_reached": "动态观察达到上限，返回当前已加载内容",
        "scroll_limit_reached": "滚动达到上限，页面可能还有更多内容",
    }
    warnings = result.get("warnings", [])
    if isinstance(warnings, list) and warnings:
        descriptions = [warning_labels.get(value, value) for value in warnings if isinstance(value, str)]
        if descriptions:
            lines.append("提示: " + "；".join(descriptions))
    lines.extend(["", "网页内容（外部资料）:", result["content"]])
    return "\n".join(lines)


def main():
    try:
        if len(sys.argv) != 2:
            raise ValueError("缺少工具参数 JSON 文件")
        with open(sys.argv[1], encoding="utf-8") as input_file:
            args = json.load(input_file)
        if not isinstance(args, dict):
            raise ValueError("工具参数必须是 JSON 对象")
        payload = build_payload(args)
        result = request_pageweave(payload)
        output = format_result(result, payload["url"])
        if "query" in args:
            output = f"搜索关键词: {args['query'].strip()}\n" + output
        print(output)
    except (ValueError, RuntimeError, OSError) as error:
        print(f"工具执行失败: {error}")
        sys.exit(1)


if __name__ == "__main__":
    main()
